static inline int
UTF8_strlen(const char *val)
{
	const unsigned char *s = (const unsigned char *) val;
	int pos = 0;

	while (*s) {
		int c = *s++;

		pos++;
		if (c < 0xC0)
			continue;
		if (*s++ < 0x80)
			return int_nil;
		if (c < 0xE0)
			continue;
		if (*s++ < 0x80)
			return int_nil;
		if (c < 0xF0)
			continue;
		if (*s++ < 0x80)
			return int_nil;
		if (c < 0xF8)
			continue;
		if (*s++ < 0x80)
			return int_nil;
		if (c < 0xFC)
			continue;
		if (*s++ < 0x80)
			return int_nil;
	}
	return pos;
}

static lng
size_unit(const char *suffix)
{
	if (suffix[0] == '\0')
		return 1;
	else if (strcasecmp("k", suffix) == 0)
		return 1000L;
	else if (strcasecmp("kib", suffix) == 0)
		return 1024L;
	else if (strcasecmp("m", suffix) == 0)
		return 1000L * 1000L;
	else if (strcasecmp("mib", suffix) == 0)
		return 1024L * 1024L;
	else if (strcasecmp("g", suffix) == 0)
		return 1000L * 1000L * 1000L;
	else if (strcasecmp("gib", suffix) == 0)
		return 1024L * 1024L * 1024L;
	else
		return -1;
}

static bool
looks_like_url(const char *text)
{
	if (text == NULL)
		return false;
	for (const char *p = text; *p != '\0'; p++) {
		if (*p == ':') {
			// Exclude :bla and c:\temp
			return p - text > 1;
		}
		if (*p < 'a' || *p > 'z') {
			return false;
		}
	}
	// we ran out of string looking for the colon
	return false;
}


